const { execFile } = require('child_process');

exports.runPing = (host, callback) => {
    // Use execFile with an argument array; no shell is spawned.
    // Additionally validate the host against a strict allow-list / IP format if required.
    const ipv4Pattern = /^[0-9]{1,3}(\.[0-9]{1,3}){3}$/;
    const hostnamePattern = /^[a-zA-Z0-9.-]+$/;
    if (!ipv4Pattern.test(host) && !hostnamePattern.test(host)) {
        return callback(new Error('Invalid host'), null);
    }
    execFile('ping', ['-c', '4', host], callback);
};

