const ALLOWED_PATHS = new Set(['/home', '/dashboard', '/settings']);

exports.redirect = (req, res) => {
    const target = req.query.url;
    if (!target) {
        return res.redirect('/');
    }
    try {
        const url = new URL(target, 'https://trusted.example');
        if (url.origin !== 'https://trusted.example') {
            return res.redirect('/');
        }
        if (!ALLOWED_PATHS.has(url.pathname)) {
            return res.redirect('/');
        }
        return res.redirect(url.pathname + url.search);
    } catch (e) {
        return res.redirect('/');
    }
};

